        private void win() {
            if (maintimer == 0) {
                this.bbonus = this.elevens * SPEED;
                this.cardnumber = 52;
                this.cardremain = 0;
                this.round++;
                this.win = 1;
                this.score += this.bbonus;
            }
            if (this.cardonev == 0 && this.card2v == 0 && this.card5v == 0) {
                this.bbonus = (this.cardremain * SPEED) + (maintimer / 10) + (this.elevens * SPEED);
                this.win = 1;
                this.round++;
                this.card5v = 1;
                this.score += this.bbonus;
            }
            if (this.win == 0) {
                this.cardnumber = 52;
                this.cardremain = 0;
                this.bbonus = (this.elevens * SPEED) + (maintimer / 10);
