    public GameView(Context context, AttributeSet attrs) {
        super(context, attrs);
        SurfaceHolder holder = getHolder();
        holder.addCallback(this);
        this.thread = new GameThread(holder, context, new Handler() { // from class: com.cg4k.elevensup2.GameView.1
            @Override // android.os.Handler
            public void handleMessage(Message m) {
                int vis = m.getData().getInt("viz");
                GameView.this.mStatusText.setVisibility(vis);
                GameView.this.mStatusText.setText(m.getData().getString("text"));
                if (vis == 0) {
                    GameView.this.mAd.requestFreshAd();
                }
                GameView.this.mAd.setVisibility(vis);
            }
        });
        setFocusable(true);
    }

    public GameThread getThread() {
        return this.thread;
    }

    @Override // android.view.View
    public boolean onTouchEvent(MotionEvent e) {
        return this.thread.onTouchEvent(e);
    }

    @Override // android.view.View
    public void onWindowFocusChanged(boolean hasWindowFocus) {
        if (!hasWindowFocus) {
            this.thread.pause();
        }
    }

    public void setTextView(TextView textView, AdView adView) {
        this.mStatusText = textView;
        this.mAd = adView;
    }

    @Override // android.view.SurfaceHolder.Callback
    public void surfaceChanged(SurfaceHolder holder, int format, int width, int height) {
        this.thread.setSurfaceSize(width, height);
    }

    @Override // android.view.SurfaceHolder.Callback
    public void surfaceCreated(SurfaceHolder holder) {
        this.thread.setRunning(true);
        this.thread.start();
    }

    @Override // android.view.SurfaceHolder.Callback
    public void surfaceDestroyed(SurfaceHolder holder) {
        boolean retry = true;
        this.thread.setRunning(false);
        while (retry) {
            try {
                this.thread.join();
                retry = false;
            } catch (InterruptedException e) {
            }
        }
    }
}

