    private Mac getNewHmacSha1(String privateKey) {
        SecretKey secretKey = new SecretKeySpec(privateKey.getBytes(), "HmacSHA1");
        try {
            Mac mac = Mac.getInstance("HmacSHA1");
            try {
                mac.init(secretKey);
